arguments.command:
cat > /app/output/final_report.html << 'HTMLEOF'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Airbnb Market Comparison: Pricing, Supply & Guest Demand Across Major Cities</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #f8f9fb;
    --card: #ffffff;
    --border: #e2e6ea;
    --accent1: #1a56db;
    --accent2: #0ea5e9;
    --accent3: #10b981;
    --accent4: #f59e0b;
    --accent5: #ef4444;
    --accent6: #8b5cf6;
    --accent7: #ec4899;
    --text-primary: #111827;
    --text-secondary: #6b7280;
    --text-muted: #9ca3af;
    --warning: #d97706;
    --warning-bg: #fffbeb;
    --warning-border: #fde68a;
    --tag-bg: #eff6ff;
    --tag-text: #1d4ed8;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
    background: var(--bg);
    color: var(--text-primary);
    font-size: 14px;
    line-height: 1.6;
  }

  /* ── HEADER ── */
  .report-header {
    background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 50%, #1a56db 100%);
    color: white;
    padding: 56px 60px 48px;
  }
  .report-header .label {
    font-size: 11px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #93c5fd;
    margin-bottom: 16px;
  }
  .report-header h1 {
    font-size: 32px;
    font-weight: 700;
    line-height: 1.25;
    max-width: 720px;
    margin-bottom: 16px;
  }
  .report-header .subtitle {
    font-size: 15px;
    color: #bfdbfe;
    max-width: 680px;
    line-height: 1.7;
  }
  .report-header .meta {
    display: flex;
    gap: 32px;
    margin-top: 32px;
    padding-top: 24px;
    border-top: 1px solid rgba(255,255,255,0.15);
  }
  .report-header .meta-item { font-size: 12px; }
  .report-header .meta-item .meta-label { color: #93c5fd; text-transform: uppercase; letter-spacing: 1px; font-size: 10px; }
  .report-header .meta-item .meta-val { font-weight: 600; font-size: 13px; margin-top: 2px; }

  /* ── LAYOUT ── */
  .container { max-width: 1200px; margin: 0 auto; padding: 0 40px; }
  .main-content { padding: 48px 0 80px; }

  /* ── DATA NOTE ── */
  .data-note {
    background: var(--warning-bg);
    border: 1px solid var(--warning-border);
    border-left: 4px solid var(--warning);
    border-radius: 8px;
    padding: 16px 20px;
    margin-bottom: 32px;
    font-size: 13px;
    color: #78350f;
  }
  .data-note strong { color: #92400e; }

  /* ── SECTION ── */
  .section { margin-bottom: 56px; }
  .section-header {
    display: flex;
    align-items: baseline;
    gap: 14px;
    margin-bottom: 24px;
    padding-bottom: 14px;
    border-bottom: 2px solid var(--border);
  }
  .section-number {
    font-size: 12px;
    font-weight: 700;
    color: var(--accent1);
    background: var(--tag-bg);
    padding: 2px 8px;
    border-radius: 4px;
    letter-spacing: 1px;
  }
  .section-title { font-size: 20px; font-weight: 700; color: var(--text-primary); }
  .section-desc { font-size: 13px; color: var(--text-secondary); margin-bottom: 24px; }

  /* ── KPI CARDS ── */
  .kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-bottom: 36px; }
  .kpi-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }
  .kpi-card.blue::before { background: var(--accent1); }
  .kpi-card.green::before { background: var(--accent3); }
  .kpi-card.amber::before { background: var(--accent4); }
  .kpi-card.purple::before { background: var(--accent6); }
  .kpi-card.pink::before { background: var(--accent7); }
  .kpi-label { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 8px; }
  .kpi-value { font-size: 26px; font-weight: 800; color: var(--text-primary); line-height: 1.1; }
  .kpi-sub { font-size: 11px; color: var(--text-secondary); margin-top: 4px; }

  /* ── CARDS & CHARTS ── */
  .card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 20px;
  }
  .card-title { font-size: 14px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px; }
  .card-desc { font-size: 12px; color: var(--text-secondary); margin-bottom: 20px; }
  .chart-wrap { position: relative; }
  .chart-wrap canvas { max-width: 100%; }

  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }

  /* ── TABLE ── */
  .table-wrap { overflow-x: auto; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  th {
    background: #f3f4f6;
    font-weight: 600;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--text-secondary);
    padding: 10px 12px;
    text-align: left;
    border-bottom: 2px solid var(--border);
  }
  td { padding: 10px 12px; border-bottom: 1px solid #f3f4f6; }
  tr:hover td { background: #fafbff; }
  .rank { font-weight: 700; color: var(--accent1); }
  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 600;
  }
  .badge-high { background: #fee2e2; color: #991b1b; }
  .badge-med { background: #fef3c7; color: #92400e; }
  .badge-low { background: #d1fae5; color: #065f46; }
  .na { color: var(--text-muted); font-style: italic; font-size: 11px; }

  /* ── BAR FILL ── */
  .bar-cell { display: flex; align-items: center; gap: 8px; }
  .bar-bg { height: 6px; background: #e5e7eb; border-radius: 3px; flex: 1; max-width: 100px; }
  .bar-fill { height: 6px; border-radius: 3px; }

  /* ── KEY TAKEAWAYS ── */
  .takeaway-list { list-style: none; counter-reset: takeaway; }
  .takeaway-list li {
    counter-increment: takeaway;
    display: flex;
    gap: 16px;
    padding: 18px 0;
    border-bottom: 1px solid var(--border);
  }
  .takeaway-list li:last-child { border-bottom: none; }
  .takeaway-num {
    font-size: 28px;
    font-weight: 900;
    color: #e5e7eb;
    min-width: 36px;
    line-height: 1;
    padding-top: 2px;
  }
  .takeaway-content h4 { font-size: 14px; font-weight: 700; margin-bottom: 4px; }
  .takeaway-content p { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }
  .takeaway-content .data-point {
    display: inline-block;
    background: var(--tag-bg);
    color: var(--tag-text);
    font-size: 11px;
    font-weight: 600;
    padding: 2px 7px;
    border-radius: 4px;
    margin: 2px 2px 0 0;
  }

  /* ── LEGEND ── */
  .legend { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 12px; }
  .legend-item { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--text-secondary); }
  .legend-dot { width: 10px; height: 10px; border-radius: 2px; flex-shrink: 0; }

  /* ── INSIGHT BOX ── */
  .insight-box {
    background: linear-gradient(135deg, #eff6ff, #f0fdf4);
    border: 1px solid #bfdbfe;
    border-radius: 8px;
    padding: 14px 18px;
    font-size: 13px;
    color: #1e40af;
    margin-top: 12px;
  }
  .insight-box strong { color: #1e3a8a; }

  /* ── FOOTER ── */
  .report-footer {
    background: #1f2937;
    color: #9ca3af;
    padding: 24px 60px;
    font-size: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .report-footer a { color: #60a5fa; text-decoration: none; }

  @media (max-width: 900px) {
    .kpi-grid { grid-template-columns: repeat(3, 1fr); }
    .grid-2 { grid-template-columns: 1fr; }
    .grid-3 { grid-template-columns: 1fr; }
    .report-header { padding: 32px 24px; }
    .container { padding: 0 20px; }
  }
</style>
</head>
<body>

<!-- HEADER -->
<div class="report-header">
  <div class="label">Cross-Market Analytics Report &bull; Hospitality Intelligence</div>
  <h1>Global Airbnb Market Comparison:<br>Pricing, Supply &amp; Guest Demand</h1>
  <p class="subtitle">
    A data-driven cross-city analysis of 50,000 Airbnb listings across seven major global tourist destinations —
    examining pricing dynamics, room-type distribution, professional host concentration, and guest engagement to
    support market-entry, investment, and regulatory benchmarking decisions.
  </p>
  <div class="meta">
    <div class="meta-item">
      <div class="meta-label">Markets Covered</div>
      <div class="meta-val">Amsterdam · Bangkok · Barcelona · London · Paris · Rome · Sydney</div>
    </div>
    <div class="meta-item">
      <div class="meta-label">Total Listings Analyzed</div>
      <div class="meta-val">50,000</div>
    </div>
    <div class="meta-item">
      <div class="meta-label">Data Scrape Date</div>
      <div class="meta-val">29 March 2026</div>
    </div>
    <div class="meta-item">
      <div class="meta-label">Data Source</div>
      <div class="meta-val">Inside Airbnb (CC BY 4.0)</div>
    </div>
  </div>
</div>

<!-- MAIN -->
<div class="container">
<div class="main-content">

<!-- DATA QUALITY NOTE -->
<div class="data-note">
  <strong>&#9888; Data Quality Disclosure:</strong>
  The source dataset contains 7 cities, not 10 as described in the original brief.
  New York, Los Angeles, and Tokyo are absent from this extract.
  Additionally, <strong>Paris and Sydney have no price data</strong> (100% null in the <code>price</code> column) —
  these two cities are excluded from all pricing comparisons but are included in all other analyses.
  Bangkok prices appear to be in Thai Baht (THB) rather than USD, based on the magnitude of values
  (median 1,400 THB ≈ USD 40); this is flagged where applicable.
  No values have been fabricated or imputed.
</div>

<!-- ══════════════════════════════════════════════════════════ -->
<!-- SECTION 1: GLOBAL MARKET OVERVIEW -->
<!-- ══════════════════════════════════════════════════════════ -->
<div class="section" id="market-overview">
  <div class="section-header">
    <span class="section-number">01</span>
    <span class="section-title">Global Market Overview</span>
  </div>
  <p class="section-desc">
    Scale and composition of each market — listing volumes, room-type mix, and overall supply structure.
  </p>

  <!-- KPI row -->
  <div class="kpi-grid">
    <div class="kpi-card blue">
      <div class="kpi-label">Total Listings</div>
      <div class="kpi-value">50,000</div>
      <div class="kpi-sub">Across 7 global cities</div>
    </div>
    <div class="kpi-card green">
      <div class="kpi-label">Largest Market</div>
      <div class="kpi-value">London</div>
      <div class="kpi-sub">16,674 listings (33.3%)</div>
    </div>
    <div class="kpi-card amber">
      <div class="kpi-label">Avg Entire Home Share</div>
      <div class="kpi-value">73.6%</div>
      <div class="kpi-sub">Across all markets</div>
    </div>
    <div class="kpi-card purple">
      <div class="kpi-label">Total Reviews</div>
      <div class="kpi-value">1.59M</div>
      <div class="kpi-sub">Cumulative across all cities</div>
    </div>
    <div class="kpi-card pink">
      <div class="kpi-label">Most Concentrated</div>
      <div class="kpi-value">Bangkok</div>
      <div class="kpi-sub">60.4% professional hosts</div>
    </div>
  </div>

  <div class="grid-2">
    <div class="card">
      <div class="card-title">Listing Volume by City</div>
      <div class="card-desc">Number of Airbnb listings per city in this dataset extract</div>
      <div class="chart-wrap" style="height:280px">
        <canvas id="listingVolumeChart"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Room Type Distribution by City</div>
      <div class="card-desc">Share of each listing type as a percentage of total city supply</div>
      <div class="chart-wrap" style="height:280px">
        <canvas id="roomTypeChart"></canvas>
      </div>
    </div>
  </div>

  <div class="card">
    <div class="card-title">Market Snapshot — All Cities</div>
    <div class="card-desc">Key supply metrics at a glance</div>
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>City</th>
            <th>Total Listings</th>
            <th>Entire Home %</th>
            <th>Private Room %</th>
            <th>Hotel Room %</th>
            <th>Shared Room %</th>
            <th>Entire Home Dominance</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td><strong>Paris</strong></td>
            <td>13,927</td>
            <td>88.2%</td>
            <td>10.7%</td>
            <td>0.9%</td>
            <td>0.2%</td>
            <td><span class="badge badge-high">Very High</span></td>
          </tr>
          <tr>
            <td><strong>London</strong></td>
            <td>16,674</td>
            <td>64.7%</td>
            <td>34.9%</td>
            <td>0.1%</td>
            <td>0.2%</td>
            <td><span class="badge badge-med">Medium</span></td>
          </tr>
          <tr>
            <td><strong>Amsterdam</strong></td>
            <td>1,770</td>
            <td>82.8%</td>
            <td>16.6%</td>
            <td>0.5%</td>
            <td>0.2%</td>
            <td><span class="badge badge-high">High</span></td>
          </tr>
          <tr>
            <td><strong>Barcelona</strong></td>
            <td>3,269</td>
            <td>60.2%</td>
            <td>38.9%</td>
            <td>0.4%</td>
            <td>0.5%</td>
            <td><span class="badge badge-med">Medium</span></td>
          </tr>
          <tr>
            <td><strong>Rome</strong></td>
            <td>6,386</td>
            <td>74.7%</td>
            <td>24.1%</td>
            <td>0.9%</td>
            <td>0.3%</td>
            <td><span class="badge badge-high">High</span></td>
          </tr>
          <tr>
            <td><strong>Bangkok</strong></td>
            <td>4,961</td>
            <td>65.8%</td>
            <td>32.0%</td>
            <td>1.1%</td>
            <td>1.0%</td>
            <td><span class="badge badge-med">Medium</span></td>
          </tr>
          <tr>
            <td><strong>Sydney</strong></td>
            <td>3,013</td>
            <td>79.0%</td>
            <td>20.3%</td>
            <td>0.6%</td>
            <td>0.2%</td>
            <td><span class="badge badge-high">High</span></td>
          </tr>
        </tbody>
      </table>
    </div>
    <div class="insight-box" style="margin-top:16px">
      <strong>Key Observation:</strong> Paris stands apart with an 88.2% entire home share — the highest in the dataset —
      indicating a market overwhelmingly oriented toward full-unit rentals. Barcelona and London have the strongest
      private room supply (38.9% and 34.9% respectively), suggesting more casual host participation or regulatory
      pressure on whole-home listings.
    </div>
